import{z as A,x as l,o as e,c as i,q as r,j as s,D as E,d as t,s as d,S as n,b as o}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"TOCTOU","description":"","frontmatter":{"title":"TOCTOU","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/toctou.md","filePath":"cs/toctou.md","lastUpdated":1791063341000}'),p={name:"cs/toctou.md"};function c(T,a,f,m,h,u){const B=l("Mermaid");return e(),i("div",null,[a[2]||(a[2]=r('<h1 id="toctou" tabindex="-1">TOCTOU <a class="header-anchor" href="#toctou" aria-label="Permalink to &quot;TOCTOU&quot;">​</a></h1><div class="epigraph"><p>先检查后使用之间，客体可以换人；权限判断必须落在同一不可分割的引用上，而不是落在可被改写的路径名上。</p><footer>—— 据 Saltzer and Schroeder 对完整中介；Anderson；文件系统 TOCTOU 的经典机制叙述</footer></div><p><a href="/cs/capability-vs-acl">上一课</a>对照了能力与 ACL。本课不重讲混淆代理人。缺口是时间：在 <code>stat</code> 与 <code>open</code> 之间，路径指向的 inode 可以变。这是完整中介失败，不是新的矩阵形状。防御是原子打开、对已打开描述符检查、用能力当稳定引用。缓冲区溢出下一课是另一类内存错误。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>能力课留下「持票即允许」。许多 API 却用路径名两次：一次检查，一次使用。两次解析可以落到不同客体上。缺口是<strong>检查与使用的绑定</strong>。本课只讲机制与防御合同，不给可复现的利用序列。</p><p><span class="marginnote">直觉类比：先「看一眼工牌」再「放人进门」，两步之间工牌可以递给别人。TOCTOU 的缝就在这两步之间——被检查的不是进门的那个人，而是递工牌的那个瞬间。</span></p><p><span class="marginnote">网络上的同类缝是「先查会话再办事」之间会话被换。对象不同，结构同构：缺少单一引用上的原子判决。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>防御：一次系统调用完成「按意图打开」（目录文件描述符 + 不跟随、或等价的安全打开）；之后只对 fd 做 <code>fstat</code>/<code>fchmod</code>。把路径换成能力或 fd 传递。锁与事务在数据库里解决的是另一对象上的同一句话：判决与更新同一快照。本课不写具体攻击者操作。</p>',9)),(e(),s(n,null,{default:E(()=>[d(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAME%5B%22%E8%B7%AF%E5%BE%84%E5%90%8D%E6%A3%80%E6%9F%A5%22%5D%20--%3E%20GAP%5B%22%E4%B8%AD%E9%97%B4%E7%8A%B6%E6%80%81%E5%8F%AF%E6%94%B9%22%5D%0A%20%20GAP%20--%3E%20USE%5B%22%E4%BD%BF%E7%94%A8%E6%97%B6%E5%B7%B2%E6%98%AF%E5%8F%A6%E4%B8%80%E5%AE%A2%E4%BD%93%22%5D%0A%20%20FD%5B%22%E6%89%93%E5%BC%80%E5%BE%97%E5%88%B0%E7%A8%B3%E5%AE%9A%20fd%22%5D%20--%3E%20SAME%5B%22%E9%9A%8F%E5%90%8E%E5%8F%AA%E5%AF%B9%E5%90%8C%E4%B8%80%E5%BC%95%E7%94%A8%E5%88%A4%E5%86%B3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[t("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"TOCTOU 破坏引用监视器的「每次访问都检查」——检查的不是后来那次访问的客体。能力与 Unix fd 把客体钉成句柄，路径只在获得句柄时解析一次。后课内存破坏是改返回地址，不是换路径。",-1)),(e(),s(n,null,{default:E(()=>[d(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E6%97%B6%E5%88%BB%201%3A%20%E7%A8%8B%E5%BA%8F%20stat%20%E6%9F%90%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20T2%5B%22%E6%97%B6%E5%88%BB%202%3A%20%E6%94%BB%E5%87%BB%E8%80%85%E6%8A%8A%E8%AF%A5%E8%B7%AF%E5%BE%84%E6%8D%A2%E6%88%90%E7%AC%A6%E5%8F%B7%E9%93%BE%E6%8E%A5%22%5D%0A%20%20T2%20--%3E%20T3%5B%22%E6%97%B6%E5%88%BB%203%3A%20%E7%A8%8B%E5%BA%8F%20open%20%E5%90%8C%E4%B8%80%E8%B7%AF%E5%BE%84%22%5D%0A%20%20T3%20--%3E%20R%5B%22%E6%89%93%E5%BC%80%E7%9A%84%E5%B7%B2%E6%98%AF%E5%8F%A6%E4%B8%80%E4%B8%AA%E5%AE%A2%E4%BD%93%22%5D%0A%20%20FIX%5B%22%E4%BF%AE%E5%A4%8D%3A%20%E4%B8%80%E6%AD%A5%20open%20%E7%9B%B4%E6%8E%A5%E6%8B%BF%20fd%22%5D%20--%3E%20FS%5B%22fstat%20%E5%90%8C%E4%B8%80%20fd%2C%E5%88%A4%E5%86%B3%E4%B8%8E%E4%BD%BF%E7%94%A8%E7%BB%91%E5%90%8C%E4%B8%80%E5%BC%95%E7%94%A8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">数字实例：<code>stat</code> 与 <code>open</code> 是两次独立系统调用，中间隔着微秒到毫秒；攻击脚本每秒可切换符号链接上千次。撞中窗口只是概率问题——所以防御要消灭窗口本身，而不是赌它撞不上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部竞态类漏洞分类写成清单。越界写如何碰到控制数据，下一课只讲机制直觉与防御，仍无利用配方。</p><p>后课默认：判决必须绑在稳定引用上。内存里的越界是另一边界。</p><p><span class="marginnote">常见误区：以为加把锁、或在 open 前再 stat 一次就安全。重查仍是路径名判决，窗口只是变窄；只有把判决绑到打开后的 fd 或能力这类稳定引用上，检查与使用才真正不可分割。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TOCTOU：检查与使用之间客体被替换。</li><li>防御是原子打开与句柄上的再检查。</li><li>缓冲区溢出直觉下一课。</li><li>出处：Saltzer and Schroeder；Anderson。</li></ul>',7))])}const _=A(p,[["render",c]]);export{F as __pageData,_ as default};
